class Invoice {
  items: { price: number; qty: number }[] = [];
  addItem(it: any) { this.items.push(it); }
}
class InvoicePrinter {
  printTotal(inv: Invoice) {
    const total = inv.items.reduce((s, i) => s + i.price * i.qty, 0);
    console.log(total);
  }
}

class UserAccount {
  sessions: { id: string; lastSeen: number }[] = [];
  addSession(s: any) { this.sessions.push(s); }
}
class SessionManager {
  expireIdle(account: UserAccount) {
    const now = Date.now();
    account.sessions = account.sessions.filter(s => now - s.lastSeen < 30 * 60 * 1000);
  }
}

// Version A
class Payment {
  private lineItems = [{ amount: 0 }];
  getAuditData() { return this.lineItems.map(li => ({ amount: li.amount })); }
}
class AuditService {
  record(payment: Payment) { const data = payment.getAuditData(); sendToAudit(data); }
}

// Version B
class PaymentV {
  lineItems = [{ amount: 0 }];
}
class AuditServiceV {
  record(p: PaymentV) { const total = p.lineItems.reduce((s, i) => s + i.amount, 0); sendToAudit(total); }
}
